import * as THREE from 'three';import {createToyKit} from '../world/toy-kit.js';import {createFish} from './view.js';
export function createFishPlatter(fishId){const root=new THREE.Group();root.name='keepsake.fish-platter.'+fishId;const {cylinder,sphere}=createToyKit(root);cylinder(.52,.49,.035,'#c6d9d4',0,.025,0);cylinder(.46,.46,.018,'#fff1d4',0,.052,0);const fish=createFish(fishId);fish.scale.setScalar(.83);fish.rotation.x=Math.PI/2;fish.position.set(.035,.14,0);root.add(fish);const seen=new Set();fish.traverse(o=>{if(o.material&&!seen.has(o.material)){seen.add(o.material);const hex=o.material.color.getHexString();if(!['294851','fff8e4'].includes(hex))o.material.color.lerp(new THREE.Color('#d3a46b'),.78);}});for(const x of [-.33,-.22])sphere(.09,'#eadb88',x,.092,.22,1,.22,1);sphere(.09,'#87a978',-.3,.10,-.20,.8,.16,1.3);return root;}
